function uniq(addrs: readonly string[]): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const a of addrs) {
    const t = a.trim();
    if (!t || seen.has(t)) continue;
    seen.add(t);
    out.push(t);
  }
  return out;
}

export const ROSEN_TRIGGER_ADDRESSES: readonly string[] = uniq([
  ...ROSEN_CHAINS.map((c) => c.trigger),
  ...ROSEN_HISTORY_TRIGGERS,
]);
export const ROSEN_PERMIT_ADDRESSES: readonly string[] = uniq([
  ...ROSEN_CHAINS.map((c) => c.permit),
  ...ROSEN_HISTORY_PERMITS,
]);
export const ROSEN_FRAUD_ADDRESSES: readonly string[] = uniq([
  ...ROSEN_CHAINS.map((c) => c.fraud),
  ...ROSEN_HISTORY_FRAUDS,
]);
export const ROSEN_RWT_IDS: readonly string[] = uniq([
  ...ROSEN_CHAINS.map((c) => c.rwtId),
  ...ROSEN_HISTORY_RWT.map((r) => r.rwtId),
]);

const ROSEN_ERGO_SET = new Set(
  uniq([
    ...ROSEN_ERGO_CONTRACTS,
    ...ROSEN_TRIGGER_ADDRESSES,
    ...ROSEN_PERMIT_ADDRESSES,
    ...ROSEN_FRAUD_ADDRESSES,
  ])
);

const TRIGGER_SET = new Set(ROSEN_TRIGGER_ADDRESSES);
const PERMIT_SET = new Set(ROSEN_PERMIT_ADDRESSES);
const FRAUD_SET = new Set(ROSEN_FRAUD_ADDRESSES);

const CHAIN_IDS = new Set<string>([
  "ergo",
  "cardano",
  "binance",
  "bitcoin",
  "bitcoin-runes",
  "ethereum",
  "doge",
  "firo",
]);

export const RWT_TO_CHAIN: ReadonlyMap<string, RosenChainId> = new Map([
  ...ROSEN_CHAINS.map((c) => [c.rwtId.toLowerCase(), c.id] as const),
  ...ROSEN_HISTORY_RWT.filter((r) => CHAIN_IDS.has(r.chain)).map(
    (r) => [r.rwtId.toLowerCase(), r.chain as RosenChainId] as const
  ),
]);

export function isRosenContractAddress(address: string | null | undefined): boolean {
  const a = address?.trim() ?? "";
  return a.length > 0 && ROSEN_ERGO_SET.has(a);
}

export function isRosenTriggerAddress(address: string | null | undefined): boolean {
  const a = address?.trim() ?? "";
  return a.length > 0 && TRIGGER_SET.has(a);
}

export function isRosenPermitAddress(address: string | null | undefined): boolean {
  const a = address?.trim() ?? "";
  return a.length > 0 && PERMIT_SET.has(a);
}

export function isRosenFraudAddress(address: string | null | undefined): boolean {
  const a = address?.trim() ?? "";
  return a.length > 0 && FRAUD_SET.has(a);
}

export function chainForRwt(rwtId: string | null | undefined): RosenChainId | null {
  if (!rwtId) return null;
  return RWT_TO_CHAIN.get(rwtId.trim().toLowerCase()) ?? null;
}

export function chainLabel(id: string | null | undefined): string {
  switch (id) {
    case "ergo":
      return "Ergo";
    case "cardano":
      return "Cardano";
    case "binance":
      return "BNB";
    case "bitcoin":
      return "Bitcoin";
    case "bitcoin-runes":
      return "Runes";
    case "ethereum":
      return "ETH";
    case "doge":
      return "Doge";
    case "firo":
      return "Firo";
    default:
      return id?.trim() ? id : "—";
  }
}
